// Initialize section processing with input validation
const inputData = $input.first().json;

// Check if we have input data
if (!inputData) {
  throw new Error('No input data received from webhook trigger');
}

// Extract required inputs with fallbacks
const companyId = inputData.company_id || 'unknown_company';
const companyName = inputData.company_name || inputData.name || 'Unknown Company';
const companyFolderName = inputData.company_folder_name || inputData.folder_name || companyName;
const sectionNumber = REPLACE_WITH_SECTION_NUMBER; // Replace with actual section number (1-20)

// Section configuration (customize for each section)
const sectionConfig = {
  1: { title: "Executive Summary", description: "High-level overview and key findings" },
  2: { title: "Company Overview", description: "Business model, products, and services" },
  3: { title: "Market Analysis", description: "Industry landscape and competitive position" },
  4: { title: "Financial Performance", description: "Revenue, profitability, and financial health" },
  5: { title: "Management Team", description: "Leadership analysis and organizational structure" },
  6: { title: "Technology & IP", description: "Intellectual property and technology assets" },
  7: { title: "Operations", description: "Operational efficiency and scalability" },
  8: { title: "Legal & Compliance", description: "Legal standing and regulatory compliance" },
  9: { title: "Risk Assessment", description: "Key risks and mitigation strategies" },
  10: { title: "Growth Opportunities", description: "Expansion potential and market opportunities" },
  11: { title: "Customer Analysis", description: "Customer base and satisfaction metrics" },
  12: { title: "Supply Chain", description: "Vendor relationships and supply chain resilience" },
  13: { title: "ESG Factors", description: "Environmental, social, and governance considerations" },
  14: { title: "Competitive Landscape", description: "Competitive analysis and market positioning" },
  15: { title: "Investment Highlights", description: "Key investment merits and value proposition" },
  16: { title: "Synergies & Integration", description: "Potential synergies and integration considerations" },
  17: { title: "Valuation Analysis", description: "Valuation methodologies and fair value assessment" },
  18: { title: "Transaction Structure", description: "Deal terms and structure recommendations" },
  19: { title: "Post-Acquisition Plan", description: "Integration roadmap and value creation plan" },
  20: { title: "Recommendations", description: "Final recommendations and next steps" }
};

const currentSection = sectionConfig[sectionNumber];

if (!currentSection) {
  throw new Error(`Invalid section number: ${sectionNumber}. Must be between 1-20.`);
}

console.log(`🔄 STARTING SECTION ${sectionNumber}`);
console.log('═'.repeat(50));
console.log(`🏢 Company: ${companyName}`);
console.log(`📋 Section: ${currentSection.title}`);
console.log(`📝 Description: ${currentSection.description}`);
console.log(`🆔 Company ID: ${companyId}`);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyFolderName,
    section_number: sectionNumber,
    section_title: currentSection.title,
    section_description: currentSection.description,
    processing_status: 'initialized',
    attempt_count: 1,
    max_attempts: 3,
    started_at: new Date().toISOString()
  }
};

// Prepare context for LLM generation
const sectionInfo = $node["Initialize Section"].json;
const previousSections = $node["Fetch Previous Sections"].json || [];
const ragResults = $node["RAG Knowledge Retrieval"].json || [];

// Build previous sections context
let previousSectionsContext = '';
if (Array.isArray(previousSections) && previousSections.length > 0) {
  previousSectionsContext = previousSections.map(section => 
    `## Section ${section.section_number}: ${section.title}\n${section.content}\n`
  ).join('\n');
} else {
  previousSectionsContext = 'No previous sections available yet.';
}

// Build RAG knowledge context
let knowledgeContext = '';
if (Array.isArray(ragResults) && ragResults.length > 0) {
  knowledgeContext = ragResults.map((result, index) => 
    `Knowledge ${index + 1}: ${result.pageContent}`
  ).join('\n\n');
} else {
  knowledgeContext = 'No relevant knowledge found in the company documents.';
}

// Create comprehensive prompt for the Maker
const makerPrompt = `You are a senior due diligence analyst generating Section ${sectionInfo.section_number}: "${sectionInfo.section_title}" for ${sectionInfo.company_name}.

SECTION REQUIREMENTS:
- Title: ${sectionInfo.section_title}
- Description: ${sectionInfo.section_description}
- Length: 800-1200 words
- Format: Professional, well-structured markdown
- Must be factual and based on available evidence

COMPANY KNOWLEDGE BASE:
${knowledgeContext}

PREVIOUS SECTIONS FOR CONTEXT:
${previousSectionsContext}

GENERATE A COMPREHENSIVE, FACTUAL ANALYSIS FOR THIS SECTION:
- Use only information from the knowledge base and previous sections
- Do not make unsupported claims or assumptions
- Structure with clear headings and bullet points
- Include specific data points and evidence where available
- If information is limited, clearly state the limitations
- Maintain professional tone throughout

Generate the section content now:`;

console.log(`🤖 MAKER STEP - Section ${sectionInfo.section_number}`);
console.log(`📋 Section: ${sectionInfo.section_title}`);
console.log(`📊 Knowledge items: ${Array.isArray(ragResults) ? ragResults.length : 0}`);
console.log(`📚 Previous sections: ${Array.isArray(previousSections) ? previousSections.length : 0}`);

return {
  json: {
    ...sectionInfo,
    maker_prompt: makerPrompt,
    knowledge_items_count: Array.isArray(ragResults) ? ragResults.length : 0,
    previous_sections_count: Array.isArray(previousSections) ? previousSections.length : 0,
    processing_status: 'ready_for_maker'
  }
};

// Process Maker output and prepare for Checker
const sectionInfo = $node["Prepare Maker Context"].json;
const llmResponse = $input.first().json;

let generatedContent = '';
if (llmResponse && llmResponse.response) {
  generatedContent = llmResponse.response.trim();
} else if (llmResponse && llmResponse.text) {
  generatedContent = llmResponse.text.trim();
} else {
  throw new Error('No content generated by Maker LLM');
}

if (generatedContent.length < 200) {
  throw new Error('Generated content too short - likely generation failed');
}

// Create checker prompt
const checkerPrompt = `You are a senior quality assurance analyst reviewing a due diligence section.

SECTION TO REVIEW:
Title: ${sectionInfo.section_title}
Required Description: ${sectionInfo.section_description}

GENERATED CONTENT:
${generatedContent}

EVALUATION CRITERIA:
1. FACTUAL ACCURACY: Is content based on evidence? No hallucinations?
2. COMPLETENESS: Does it cover the required scope adequately?
3. STRUCTURE: Is it well-organized with clear headings?
4. PROFESSIONAL TONE: Appropriate for due diligence report?
5. LENGTH: Appropriate depth (800-1200 words)?
6. TEMPLATE USAGE: Avoids generic templates, specific to this company?

PROVIDE YOUR ASSESSMENT:
- If APPROVED: Respond with exactly: "APPROVED"
- If REJECTED: Respond with "REJECTED" followed by specific feedback

Your assessment:`;

console.log(`🔍 CHECKER STEP - Section ${sectionInfo.section_number}`);
console.log(`📝 Content length: ${generatedContent.length} characters`);

return {
  json: {
    ...sectionInfo,
    generated_content: generatedContent,
    checker_prompt: checkerPrompt,
    processing_status: 'ready_for_checker',
    content_length: generatedContent.length
  }
};

// Process Checker feedback and determine next action
const sectionInfo = $node["Process Maker Output"].json;
const checkerResponse = $input.first().json;

let checkerFeedback = '';
if (checkerResponse && checkerResponse.response) {
  checkerFeedback = checkerResponse.response.trim();
} else if (checkerResponse && checkerResponse.text) {
  checkerFeedback = checkerResponse.text.trim();
} else {
  throw new Error('No feedback from Checker LLM');
}

const isApproved = checkerFeedback.toUpperCase().includes('APPROVED');

console.log(`🔍 CHECKER RESULT - Section ${sectionInfo.section_number}`);
console.log(`📋 Decision: ${isApproved ? '✅ APPROVED' : '❌ REJECTED'}`);
if (!isApproved) {
  console.log(`📝 Feedback: ${checkerFeedback}`);
}

return {
  json: {
    ...sectionInfo,
    checker_feedback: checkerFeedback,
    checker_approved: isApproved,
    processing_status: isApproved ? 'checker_approved' : 'checker_rejected',
    checked_at: new Date().toISOString()
  }
};

// Handle Checker rejection - prepare for retry or max attempts
const sectionInfo = $input.first().json;

if (sectionInfo.attempt_count >= sectionInfo.max_attempts) {
  console.log(`❌ MAX ATTEMPTS REACHED - Section ${sectionInfo.section_number}`);
  console.log(`📝 Final feedback: ${sectionInfo.checker_feedback}`);

  return {
    json: {
      ...sectionInfo,
      processing_status: 'failed_max_attempts',
      final_error: `Section failed after ${sectionInfo.max_attempts} attempts. Last feedback: ${sectionInfo.checker_feedback}`,
      failed_at: new Date().toISOString()
    }
  };
}

// Prepare for retry with feedback
const retryPrompt = `You are a senior due diligence analyst. Your previous attempt was rejected by quality review.

PREVIOUS FEEDBACK:
${sectionInfo.checker_feedback}

Now generate Section ${sectionInfo.section_number}: "${sectionInfo.section_title}" for ${sectionInfo.company_name}.
Address the feedback above and ensure:
- Factual accuracy based on available evidence
- Comprehensive coverage of ${sectionInfo.section_description}
- Professional structure and tone
- Appropriate length (800-1200 words)
- Company-specific content, not generic templates

Generate the improved section content now:`;

console.log(`🔄 RETRY ATTEMPT ${sectionInfo.attempt_count + 1} - Section ${sectionInfo.section_number}`);
console.log(`📝 Addressing feedback: ${sectionInfo.checker_feedback.substring(0, 100)}...`);

return {
  json: {
    ...sectionInfo,
    maker_prompt: retryPrompt,
    attempt_count: sectionInfo.attempt_count + 1,
    processing_status: 'ready_for_retry',
    retry_reason: sectionInfo.checker_feedback
  }
};

// Prepare content for Approver review
const sectionInfo = $input.first().json;

const approverPrompt = `You are a senior partner conducting final approval of a due diligence section.

SECTION FOR FINAL APPROVAL:
Title: ${sectionInfo.section_title}
Company: ${sectionInfo.company_name}

CONTENT:
${sectionInfo.generated_content}

FINAL APPROVAL CRITERIA:
1. EXECUTIVE READINESS: Suitable for C-level presentation?
2. RISK ASSESSMENT: Properly identifies and addresses risks?
3. ACTIONABLE INSIGHTS: Provides clear, actionable recommendations?
4. COMPLETENESS: Nothing critical missing for decision-making?
5. ACCURACY: All claims properly supported?

DECISION:
- If APPROVED: Respond with exactly: "APPROVED"
- If REJECTED: Respond with "REJECTED" followed by specific concerns

Your final decision:`;

console.log(`👔 APPROVER STEP - Section ${sectionInfo.section_number}`);
console.log(`📋 Ready for final approval`);

return {
  json: {
    ...sectionInfo,
    approver_prompt: approverPrompt,
    processing_status: 'ready_for_approver'
  }
};

// Process Approver decision
const sectionInfo = $node["Prepare Approver Review"].json;
const approverResponse = $input.first().json;

let approverFeedback = '';
if (approverResponse && approverResponse.response) {
  approverFeedback = approverResponse.response.trim();
} else if (approverResponse && approverResponse.text) {
  approverFeedback = approverResponse.text.trim();
} else {
  throw new Error('No feedback from Approver LLM');
}

const isApproved = approverFeedback.toUpperCase().includes('APPROVED');

console.log(`👔 APPROVER RESULT - Section ${sectionInfo.section_number}`);
console.log(`📋 Final Decision: ${isApproved ? '✅ APPROVED' : '❌ REJECTED'}`);
if (!isApproved) {
  console.log(`📝 Feedback: ${approverFeedback}`);
}

return {
  json: {
    ...sectionInfo,
    approver_feedback: approverFeedback,
    approver_approved: isApproved,
    processing_status: isApproved ? 'approver_approved' : 'approver_rejected',
    approved_at: isApproved ? new Date().toISOString() : null
  }
};

// Handle Approver rejection - back to Maker with feedback
const sectionInfo = $input.first().json;

if (sectionInfo.attempt_count >= sectionInfo.max_attempts) {
  console.log(`❌ MAX ATTEMPTS REACHED - Section ${sectionInfo.section_number}`);
  console.log(`📝 Final approver feedback: ${sectionInfo.approver_feedback}`);

  return {
    json: {
      ...sectionInfo,
      processing_status: 'failed_max_attempts',
      final_error: `Section failed final approval after ${sectionInfo.max_attempts} attempts. Approver feedback: ${sectionInfo.approver_feedback}`,
      failed_at: new Date().toISOString()
    }
  };
}

// Prepare for retry with approver feedback
const retryPrompt = `You are a senior due diligence analyst. Your section was rejected by final approval.

APPROVER FEEDBACK:
${sectionInfo.approver_feedback}

Now generate Section ${sectionInfo.section_number}: "${sectionInfo.section_title}" for ${sectionInfo.company_name}.
Address the approver's concerns and ensure:
- Executive-level quality and presentation
- Comprehensive risk assessment
- Clear, actionable insights
- All critical information for decision-making
- Properly supported claims

Generate the revised section content now:`;

console.log(`🔄 APPROVER RETRY ${sectionInfo.attempt_count + 1} - Section ${sectionInfo.section_number}`);
console.log(`📝 Addressing approver feedback: ${sectionInfo.approver_feedback.substring(0, 100)}...`);

return {
  json: {
    ...sectionInfo,
    maker_prompt: retryPrompt,
    attempt_count: sectionInfo.attempt_count + 1,
    processing_status: 'ready_for_retry',
    retry_reason: `Approver feedback: ${sectionInfo.approver_feedback}`
  }
};

// Final section completion status
const sectionInfo = $input.first().json;
const dbResult = $node["Save Approved Section"].json;

const processingTimeMinutes = Math.round((new Date() - new Date(sectionInfo.started_at)) / 1000 / 60);
const wordCount = sectionInfo.generated_content.split(' ').length;

console.log('✅ SECTION COMPLETED SUCCESSFULLY!');
console.log('═'.repeat(50));
console.log(`📋 Section ${sectionInfo.section_number}: ${sectionInfo.section_title}`);
console.log(`🏢 Company: ${sectionInfo.company_name}`);
console.log(`📝 Content: ${wordCount} words, ${sectionInfo.generated_content.length} characters`);
console.log(`🔄 Attempts: ${sectionInfo.attempt_count}/${sectionInfo.max_attempts}`);
console.log(`📊 Knowledge Used: ${sectionInfo.knowledge_items_count} items`);
console.log(`📚 Previous Sections: ${sectionInfo.previous_sections_count}`);
console.log(`⏱️ Processing Time: ${processingTimeMinutes} minutes`);
console.log('═'.repeat(50));

return {
  json: {
    section_number: sectionInfo.section_number,
    title: sectionInfo.section_title,
    content: sectionInfo.generated_content,
    status: 'approved',
    company_id: sectionInfo.company_id,
    company_name: sectionInfo.company_name,
    word_count: wordCount,
    character_count: sectionInfo.generated_content.length,
    attempt_count: sectionInfo.attempt_count,
    processing_time_minutes: processingTimeMinutes,
    knowledge_items_used: sectionInfo.knowledge_items_count,
    previous_sections_referenced: sectionInfo.previous_sections_count,
    checker_feedback: sectionInfo.checker_feedback,
    approver_feedback: sectionInfo.approver_feedback,
    started_at: sectionInfo.started_at,
    approved_at: sectionInfo.approved_at,
    completed_at: new Date().toISOString()
  }
};

// Handle final failure cases
const sectionInfo = $input.first().json;

console.log('❌ SECTION PROCESSING FAILED');
console.log('═'.repeat(50));
console.log(`📋 Section ${sectionInfo.section_number}: ${sectionInfo.section_title}`);
console.log(`🏢 Company: ${sectionInfo.company_name}`);
console.log(`🔄 Attempts Made: ${sectionInfo.attempt_count}/${sectionInfo.max_attempts}`);
console.log(`❌ Final Error: ${sectionInfo.final_error || sectionInfo.retry_reason}`);
console.log('═'.repeat(50));

return {
  json: {
    section_number: sectionInfo.section_number,
    title: sectionInfo.section_title,
    status: 'failed',
    company_id: sectionInfo.company_id,
    company_name: sectionInfo.company_name,
    error: sectionInfo.final_error || sectionInfo.retry_reason,
    attempt_count: sectionInfo.attempt_count,
    started_at: sectionInfo.started_at,
    failed_at: sectionInfo.failed_at || new Date().toISOString()
  }
};
